// F-238 — the fax-packet splitter, scored against the synthetic complex referral packet's answer key
// (`fixtures/doclens-complex-packet/`, generated by scripts/doclens/make-complex-packet.py and parsed by the
// real docling-worker with each OCR engine).
import { readFileSync } from "node:fs";
import { join } from "node:path";
import {
  type ClassifiedPage,
  type SplitterPage,
  headerDate,
  splitPacket,
} from "@chartwarden/intake-extraction";
import { describe, expect, it } from "vitest";

const DIR = join(__dirname, "fixtures", "doclens-complex-packet");
interface KeyDoc {
  id: string;
  type: ClassifiedPage["documentType"];
  date: string;
  pages: [number, number];
  duplicateOf?: string;
}
const key = JSON.parse(readFileSync(join(DIR, "complex-referral-packet.key.json"), "utf8")) as {
  documents: KeyDoc[];
};
const parse = (engine: "tesseract" | "easyocr"): SplitterPage[] =>
  JSON.parse(readFileSync(join(DIR, `parse.${engine}.json`), "utf8")).pages;

const typeOfPage = new Map<number, ClassifiedPage["documentType"]>();
for (const d of key.documents)
  for (let p = d.pages[0]; p <= d.pages[1]; p++) typeOfPage.set(p, d.type);
const classify = (pages: SplitterPage[], as?: ClassifiedPage["documentType"]): ClassifiedPage[] =>
  pages.map((p) => ({
    pageNumber: p.page,
    documentType: as ?? typeOfPage.get(p.page) ?? "unknown",
    confidence: 0.9,
    needsHumanClassification: false,
  }));
const shape = (segs: { pageNumbers: readonly number[]; duplicateOfPage: number | null }[]) =>
  segs.map(
    (s) =>
      `${s.pageNumbers[0]}-${s.pageNumbers[s.pageNumbers.length - 1]}${s.duplicateOfPage ? "D" : ""}`,
  );
const expected = key.documents.map((d) => `${d.pages[0]}-${d.pages[1]}${d.duplicateOf ? "D" : ""}`);
const isoOf = (mdY: string) => {
  const [m, d, y] = mdY.split("/");
  return `${y}-${m}-${d}`;
};

describe("fax-packet splitter (complex referral packet, Tesseract OCR)", () => {
  const pages = parse("tesseract");

  it("recovers every document boundary and the re-sent page", () => {
    const segs = splitPacket(pages, classify(pages));
    expect(shape(segs)).toEqual(expected);
    const dup = segs.find((s) => s.duplicateOfPage !== null);
    expect(dup).toMatchObject({ pageNumbers: [12], duplicateOfPage: 9, boundary: "duplicate" });
  });

  it("splits from the page layout alone: a classifier that calls every page 'consult' gives the same documents", () => {
    // Back-to-back consults (wound → nutrition; pulmonology 2025 → memory clinic 2025) are separate documents.
    expect(shape(splitPacket(pages, classify(pages, "consult")))).toEqual(expected);
  });

  it("dates each document by its own header — discharge date, never the DOB", () => {
    const segs = splitPacket(pages, classify(pages));
    const byFirst = new Map(segs.map((s) => [s.pageNumbers[0], s.documentDate]));
    for (const d of key.documents) {
      // A cumulative lab table has no single document date; the splitter reports its first column.
      if (d.id === "labs") continue;
      expect([d.id, byFirst.get(d.pages[0])]).toEqual([d.id, isoOf(d.date)]);
    }
  });

  it("keeps multi-page documents whole and titles them from their header", () => {
    const segs = splitPacket(pages, classify(pages));
    expect(segs.find((s) => s.pageNumbers[0] === 4)).toMatchObject({
      pageNumbers: [4, 5],
      title: "DISCHARGE SUMMARY",
      documentType: "discharge_summary",
    });
  });
});

describe("splitter rules", () => {
  const page = (n: number, ...texts: [string, string][]): SplitterPage => ({
    page: n,
    blocks: texts.map(([label, text]) => ({ label, text })),
  });

  it("a sentence that merely contains 'continued' is not a page break", () => {
    const pages = [
      page(
        1,
        ["section_header", "MEMORY CLINIC"],
        ["text", "I have continued donepezil 5 mg nightly."],
      ),
      page(2, ["text", "RIVERSIDE GENERAL HOSPITAL"], ["text", "CONTINUE furosemide"]),
    ];
    const segs = splitPacket(pages, [
      { pageNumber: 1, documentType: "consult", confidence: 0.9, needsHumanClassification: false },
      {
        pageNumber: 2,
        documentType: "med_recon",
        confidence: 0.9,
        needsHumanClassification: false,
      },
    ]);
    expect(segs.map((s) => s.pageNumbers)).toEqual([[1], [2]]);
  });

  it("an explicit continuation wins over a new type verdict", () => {
    const pages = [
      page(1, ["section_header", "DISCHARGE SUMMARY"], ["text", "(continued - page 1 of 2)"]),
      page(
        2,
        ["text", "DOCLENS, ARTHUR MRN 1 - Discharge Summary - Page of 2"],
        ["section_header", "DISPOSITION"],
      ),
    ];
    const segs = splitPacket(pages, [
      {
        pageNumber: 1,
        documentType: "discharge_summary",
        confidence: 0.9,
        needsHumanClassification: false,
      },
      {
        pageNumber: 2,
        documentType: "med_recon",
        confidence: 0.6,
        needsHumanClassification: false,
      },
    ]);
    expect(segs).toHaveLength(1);
    expect(segs[0]).toMatchObject({
      pageNumbers: [1, 2],
      documentType: "discharge_summary",
      confidence: 0.6,
    });
  });

  it("an unclassifiable first page keeps its segment out of extraction", () => {
    const segs = splitPacket(
      [page(1, ["section_header", "SOMETHING"], ["text", "x"])],
      [{ pageNumber: 1, documentType: "unknown", confidence: 0.2, needsHumanClassification: true }],
    );
    expect(segs[0]?.needsHumanClassification).toBe(true);
  });

  it("reads OCR-mangled spelled dates and skips birth dates", () => {
    expect(
      headerDate(page(1, ["text", "1 Court Plaza, Salem OR 97301 March 2025"], ["text", "10,"])),
    ).toBe("2025-03-10");
    expect(headerDate(page(1, ["text", "March 1 0 , 2025"]))).toBe("2025-03-10");
    expect(
      headerDate(
        page(
          1,
          ["text", "Patient: X DOB: 03/02/1941"],
          ["text", "Admitted: 09/17/2026 Discharged: 10/01/2026"],
        ),
      ),
    ).toBe("2026-10-01");
    expect(headerDate(page(1, ["text", "DOB 03/02/1941"]))).toBeNull();
  });
});
